interface VolumetricShape extends Shape {
    public double volume();
}

public class VolumeCalculator {
    private List<VolumetricShape> shapes;

    public VolumeCalculator(List<VolumetricShape> shapes) {
        this.shapes = shapes;
    }

    public double sum() {
        double totalVolume = 0;
        for (VolumetricShape shape : shapes) {
            totalVolume += shape.volume();
        }
        return totalVolume;
    }
}
